function PageHead({ eyebrow, title, description, actions }: { eyebrow:string; title:string; description:string; actions?:React.ReactNode }) { return <div className="qf-page-head"><div><div className="qf-eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{actions && <div className="qf-actions">{actions}</div>}</div>; }
function Overview({ bugs, tests, runs, evidence, setBugModal }: { bugs:Bug[]; tests:TestCase[]; runs:TestRun[]; evidence:Evidence[]; setBugModal:(b?:Bug)=>void }) {
  const attention = bugs.filter(b=>b.status==='Open'||b.status==='In Progress').length;
  const executed = runs.reduce((sum, run)=>sum+run.total, 0);
  const passed = runs.reduce((sum, run)=>sum+run.passed, 0);
  const passRate = executed ? `${(passed/executed*100).toFixed(1)}%` : '—';
  const covered = tests.filter(test=>test.status !== 'Not run').length;
  const coverage = tests.length ? Math.round(covered/tests.length*100) : 0;
  const latest = runs[0];
  const latestTone = latest?.status === 'Passed' ? 'passed' : latest?.status === 'In progress' ? 'progress' : 'failed';
  return <div className="qf-content"><PageHead eyebrow="Workspace / Overview" title="Good morning, Maya." description="A focused read on clone fidelity, regressions, and the next handoff." actions={<><Link href="/comparison" className="qf-button" data-testid="link-open-comparison"><GitCompare size={14}/>Compare builds</Link><Btn testId="button-create-bug-overview" className="primary" onClick={()=>setBugModal()}><Plus size={14}/>Log a bug</Btn></>}/><div className="qf-grid qf-stat-grid"><div className="qf-card qf-stat"><div className="qf-stat-label">Open bugs</div><div className="qf-stat-value" data-testid="value-open-bugs">{attention}</div><div className="qf-stat-note bad">{attention} need attention now</div></div><div className="qf-card qf-stat"><div className="qf-stat-label">Pass rate</div><div className="qf-stat-value" data-testid="value-pass-rate">{passRate}</div><div className="qf-stat-note good">{runs.length} recorded runs</div></div><div className="qf-card qf-stat"><div className="qf-stat-label">Evidence captured</div><div className="qf-stat-value" data-testid="value-evidence">{evidence.length}</div><div className="qf-stat-note good">Across {new Set(evidence.map(item=>item.module)).size} modules</div></div><div className="qf-card qf-stat"><div className="qf-stat-label">Coverage</div><div className="qf-stat-value" data-testid="value-coverage">{coverage}%</div><div className="qf-stat-note warn">{tests.length-covered} cases not run</div></div></div>{latest ? <div className="qf-two-col" style={{marginTop:15}}><section className="qf-card qf-card-pad"><div className="qf-section-head"><h2>Latest execution · {latest.id}</h2><Link href="/test-runs" className="qf-link" data-testid="link-view-run">View run <ArrowUpRight size={13} style={{verticalAlign:'middle'}}/></Link></div><div style={{display:'flex',justifyContent:'space-between',alignItems:'end',marginBottom:18}}><div><div style={{fontWeight:800,fontSize:20}}>{latest.name}</div><div className="qf-muted" style={{fontSize:12,marginTop:5}}>{latest.environment} · {latest.date}</div></div><Badge tone={latestTone}>{latest.status}</Badge></div><div className="qf-progress"><span style={{width:`${Math.round(latest.passed/latest.total*100)}%`}}/></div><div style={{display:'flex',gap:25,marginTop:13,fontSize:11}}><span className="qf-check"><CheckCircle2 size={13} style={{verticalAlign:'middle'}}/> {latest.passed} passed</span><span className="qf-fail"><AlertCircle size={13} style={{verticalAlign:'middle'}}/> {latest.failed} failed</span><span className="qf-muted"><Circle size={10} style={{verticalAlign:'middle'}}/> {latest.blocked} blocked</span></div></section><section className="qf-card qf-card-pad"><div className="qf-section-head"><h2>Attention queue</h2><Link href="/bugs" className="qf-link" data-testid="link-view-bugs">All bugs <ArrowUpRight size={13} style={{verticalAlign:'middle'}}/></Link></div>{bugs.filter(b=>b.status==='Open'||b.status==='In Progress').slice(0,3).map(b=><div key={b.id} style={{display:'flex',gap:10,padding:'11px 0',borderBottom:'1px solid #252d45'}} data-testid={`row-attention-${b.id}`}><Badge tone={b.severity.toLowerCase()}>{b.severity}</Badge><div style={{minWidth:0}}><div style={{fontSize:12,fontWeight:700,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{b.title}</div><div className="qf-mono" style={{marginTop:5}}>{b.id} · {b.module}</div></div></div>)}</section></div> : <div className="qf-card qf-empty" style={{marginTop:15}}>No test runs recorded yet.</div>}<div className="qf-two-col" style={{marginTop:15}}><section className="qf-card qf-card-pad"><div className="qf-section-head"><h2>Failure trend</h2><span>Last 7 runs</span></div><div className="qf-bars">{[42,51,48,63,56,71,81].map((h,i)=><div className="qf-bar-group" key={i}><div className={`qf-bar ${i===6?'amber':''}`} style={{height:`${h}%`}}/><span className="qf-bar-label">R{String(i+1).padStart(2,'0')}</span></div>)}</div></section><section className="qf-card qf-card-pad"><div className="qf-section-head"><h2>Coverage by module</h2><span>{coverage}% overall</span></div>{[['Signing flow',92],['Authentication',84],['Templates',71],['Responsive',58]].map(([label,val])=><div key={String(label)} style={{margin:'17px 0'}}><div style={{display:'flex',justifyContent:'space-between',fontSize:11,marginBottom:7}}><span>{label}</span><span className="qf-mono">{val}%</span></div><div className="qf-progress"><span style={{width:`${val}%`}}/></div></div>)}</section></div></div>;
}

